const TOKENS = [["--page-pad", "Side padding", "80", "48", "24", "20"], ["--section-pad", "Section padding (top and bottom)", "120", "96", "72", "64"], ["--frame-inset", "Page rails", "24", "24", "12", "8"], ["--space-xxlarge", "Header to content", "80", "64", "48", "48"], ["--h2-scale", "Section headline (60px × scale)", "1", ".8", ".6667", ".6"], ["--h1-size", "Hero headline", "69", "56", "44", "40"], ["--display-size", "Photo hero, stat figures", "70", "56", "48", "44"], ["--h4-size", "Large titles", "40", "34", "30", "28"], ["--h5-size", "Quotes, lifecycle titles", "32", "28", "26", "24"], ["--h6-size", "Carousel card titles", "28", "24", "22", "20"], ["--text-xl-size", "Post titles, the launch quote", "24", "22", "20", "20"]];
